<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yorum moderasyonu</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}.item{background:white;padding:18px;border-radius:12px;margin:12px 0;border:1px solid #e7ece8}.muted{color:#6d796f;font-size:13px}button{border:0;padding:9px 13px;border-radius:8px;color:white;background:#176b50;margin-right:5px}button.reject{background:#a43}</style></head><body><main class="wrap"><h1>Misafir yorumları</h1><?php foreach($reviews as $review): ?><article class="item"><strong><?= e($review['title']) ?></strong><div class="muted"><?= e($review['username']) ?> · <?= (int)$review['rating'] ?>/5 · <?= e($review['status']) ?></div><p><?= e($review['body']) ?></p><form method="post" action="/admin/reviews/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$review['id'] ?>"><button name="status" value="approved">Yayınla</button><button class="reject" name="status" value="rejected">Reddet</button></form></article><?php endforeach; ?><?php if(!$reviews): ?><p>Henüz değerlendirme bulunmuyor.</p><?php endif; ?><p><a href="/admin">Yönetim paneli</a></p></main></body></html>